// Un ítem por feed con url: primero los de config/feeds.json y, si Rutas trae configZona, después los de <configZona>/feeds.json.
// El orden importa: Preparar lo usa para saber qué feed es cada respuesta. configZona vacío: sin zona, como antes.
// Con <configZona>/avisos.json, cada ítem lleva además listadoAvisos (la página de comunicados de la SCPL) para «Bajar listado».
const fs = require('fs');
const rutas = $('Rutas').first().json;
const leer = archivo => JSON.parse(fs.readFileSync(rutas.carpetaRepo + '/' + archivo, 'utf8'));
const nacionales = leer('config/feeds.json').feeds.filter(f => f.url);
if (!rutas.configZona) return nacionales.map(f => ({ json: { nombre: f.nombre, url: f.url } }));
const conAvisos = fs.existsSync(rutas.carpetaRepo + '/' + rutas.configZona + '/avisos.json');
const fuente = conAvisos ? (leer(rutas.configZona + '/avisos.json').fuentes || []).find(f => f.formato === 'scpl') : null;
const listadoAvisos = (fuente && fuente.listado) || '';
const deZona = leer(rutas.configZona + '/feeds.json').feeds.filter(f => f.url).map(f => ({ json: { nombre: f.nombre, url: f.url, origen: 'zona', listadoAvisos } }));
return [...nacionales.map(f => ({ json: { nombre: f.nombre, url: f.url, origen: 'nacional', listadoAvisos } })), ...deZona];

// Qué notas de la SCPL faltan bajar (de los últimos 7 días, que valen y que no se bajaron nunca): una por ítem, para «Bajar notas».
// Sin avisos (configZona vacío o sin avisos.json), con el listado caído o sin nada que bajar: un solo ítem «nada»,
// para que la vuelta siga (n8n no corre los nodos de después de uno que no devuelve nada).
const fs = require('fs');
const rutas = $('Rutas').first().json;
const leer = archivo => JSON.parse(fs.readFileSync(rutas.carpetaRepo + '/' + archivo, 'utf8'));
const nada = [{ json: { nada: true, url: '' } }];
const dir = rutas.configZona ? rutas.carpetaRepo + '/' + rutas.configZona : null;
if (!dir || !fs.existsSync(dir + '/avisos.json')) return nada;
const l = $('Bajar listado').first().json;
const s = Number(l.statusCode) || 0;
if (l.error || s < 200 || s >= 400) return nada;
const reglas = fs.existsSync(dir + '/reglas.json') ? { ...leer('config/reglas.json'), ...leer(rutas.configZona + '/reglas.json') } : leer('config/reglas.json');
const capa4 = require(rutas.carpetaRepo + '/src/capa4.js');
const faltan = capa4.notasQueFaltan({ listadoHtml: String(l.body ?? ''), guardado: $getWorkflowStaticData('global').guardado || null,
  ahora: new Date().toISOString(), cfg: leer(rutas.configZona + '/avisos.json'), reglas });
return faltan.length ? faltan.map(x => ({ json: { nada: false, ...x } })) : nada;

const fs = require('fs');
const rutas = $('Rutas').first().json;
// La configuración se lee del disco en cada vuelta: un git pull de config/ vale desde la vuelta siguiente.
const leer = archivo => JSON.parse(fs.readFileSync(rutas.carpetaRepo + '/' + archivo, 'utf8'));
const feeds = leer('config/feeds.json').feeds.filter(f => f.url);
const portales = leer('config/portales.json').portales;
const reglas = leer('config/reglas.json');
const firmas = leer('config/firmas.json').firmas;
// La zona (Comodoro y Chubut), si Rutas trae configZona: como cargarConfig de scripts/vuelta.js (sus reglas pisan las de config/reglas.json; sin firmas).
// Con avisos.json (y cronograma-agua.json, si está), también el bloque «Avisos».
const hay = archivo => fs.existsSync(rutas.carpetaRepo + '/' + rutas.configZona + '/' + archivo);
const zona = !rutas.configZona ? null : {
  feeds: leer(rutas.configZona + '/feeds.json').feeds,
  portales: leer(rutas.configZona + '/portales.json').portales,
  reglas: hay('reglas.json') ? { ...reglas, ...leer(rutas.configZona + '/reglas.json') } : reglas,
  ...(hay('avisos.json') ? { avisos: { ...leer(rutas.configZona + '/avisos.json'), cronograma: hay('cronograma-agua.json') ? leer(rutas.configZona + '/cronograma-agua.json') : null } } : {}),
};
// src/capa4.js queda en memoria: un git pull del código vale después de reiniciar n8n.
const capa4 = require(rutas.carpetaRepo + '/src/capa4.js');
const estatico = $getWorkflowStaticData('global');
estatico.inicio = Date.now();
const ahora = new Date().toISOString();
// Cada ítem de Bajar es un feed, en el mismo orden que Feeds. Un feed caído trae `error` (On Error: Continue).
const nombres = $('Feeds').all().map(i => i.json.nombre);
const cuerpos = $('Bajar').all().map((it, k) => {
  const j = it.json;
  if (j.error) return { nombre: nombres[k], status: 0, error: String((j.error && j.error.message) || j.error) };
  return { nombre: nombres[k], status: Number(j.statusCode) || 0, xml: String(j.body ?? j.data ?? '') };
});
// Los avisos: el listado de «Bajar listado» y una respuesta de «Bajar notas» por cada ítem de «Avisos» (los «nada» no cuentan).
const fallo = j => {
  if (j.error) return String((j.error && j.error.message) || j.error);
  const s = Number(j.statusCode) || 0;
  return s >= 200 && s < 400 ? null : 'HTTP ' + s;
};
let avisos = null;
if (zona && zona.avisos) {
  const l = $('Bajar listado').first().json;
  const bajadas = $input.all();
  const notasHtml = $('Avisos').all().map((it, k) => ({ p: it.json, j: (bajadas[k] || { json: { error: 'sin respuesta' } }).json }))
    .filter(x => !x.p.nada)
    .map(({ p, j }) => ({ id: p.id, titulo: p.titulo, fecha: p.fecha, html: fallo(j) ? '' : String(j.body ?? ''), error: fallo(j) }));
  avisos = { listadoHtml: fallo(l) ? '' : String(l.body ?? ''), listadoError: fallo(l), notasHtml };
}
const u = capa4.mitadUno({ cuerpos, guardado: estatico.guardado || null, ahora, feeds, portales, reglas, firmas, zona, avisos });
estatico.guardado = u.guardado;
estatico.vuelta = { ahora, lectura: u.lectura, acumulado: u.acumulado };
if (!u.preguntas.length) return [{ json: { sinPreguntas: true, resumen: u.resumen } }];
return u.preguntas.map(q => ({ json: { sinPreguntas: false, id: q.id, cuerpoIA: capa4.cuerpoIA(q.texto, { reglas, tipo: 'juicio' }) } }));

const fs = require('fs');
const rutas = $('Rutas').first().json;
// La configuración se lee del disco en cada vuelta: un git pull de config/ vale desde la vuelta siguiente.
const leer = archivo => JSON.parse(fs.readFileSync(rutas.carpetaRepo + '/' + archivo, 'utf8'));
const feeds = leer('config/feeds.json').feeds.filter(f => f.url);
const portales = leer('config/portales.json').portales;
const reglas = leer('config/reglas.json');
const firmas = leer('config/firmas.json').firmas;
// La zona (Comodoro y Chubut), si Rutas trae configZona: como cargarConfig de scripts/vuelta.js (sus reglas pisan las de config/reglas.json; sin firmas).
// Con avisos.json (y cronograma-agua.json, si está), también el bloque «Avisos».
const hay = archivo => fs.existsSync(rutas.carpetaRepo + '/' + rutas.configZona + '/' + archivo);
const zona = !rutas.configZona ? null : {
  feeds: leer(rutas.configZona + '/feeds.json').feeds,
  portales: leer(rutas.configZona + '/portales.json').portales,
  reglas: hay('reglas.json') ? { ...reglas, ...leer(rutas.configZona + '/reglas.json') } : reglas,
  ...(hay('avisos.json') ? { avisos: { ...leer(rutas.configZona + '/avisos.json'), cronograma: hay('cronograma-agua.json') ? leer(rutas.configZona + '/cronograma-agua.json') : null } } : {}),
};
// src/capa4.js queda en memoria: un git pull del código vale después de reiniciar n8n.
const capa4 = require(rutas.carpetaRepo + '/src/capa4.js');
const estatico = $getWorkflowStaticData('global');
const v = estatico.vuelta;
const entrada = $input.all();
// Viene de la rama «false» del IF (un solo ítem con sinPreguntas) o de IA (un ítem por pregunta, en el orden de Preparar).
const preguntas = $('Preparar').all();
const respuestas = entrada.length && entrada[0].json.sinPreguntas === true ? []
  : entrada.map((it, k) => ({ id: preguntas[k].json.id, texto: capa4.textoDeRespuesta(it.json) }));
const r = capa4.mitadDos({ guardado: estatico.guardado, lectura: v.lectura, acumulado: v.acumulado, respuestas, ahora: v.ahora, feeds, portales, reglas, firmas, zona });
r.linea.tardoMs = Date.now() - estatico.inicio;
capa4.escribir({ carpetaDatos: rutas.carpetaDatos, lista: r.lista, linea: r.linea });
estatico.guardado = r.guardado;
delete estatico.vuelta;
const codigo = r.linea.feeds.ok === 0 ? 2 : 0;
return [{ json: {
  avisar: r.avisar,
  ia: r.linea.ia, provisorias: r.linea.provisorias, tardoMs: r.linea.tardoMs,
  resumen: capa4.resumenEnPantalla({ linea: r.linea, carpeta: rutas.carpetaDatos, codigo, anillos: zona ? zona.reglas.anillos || [] : [] }),
} }];
